package mx.syncro.melateretro;
import android.content.*;import android.database.*;import android.database.sqlite.*;import java.util.*;
public class Db extends SQLiteOpenHelper{public Db(Context c){super(c,"melate_retro.db",null,1);}public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE draws(contest INTEGER PRIMARY KEY,date TEXT,n1 INTEGER,n2 INTEGER,n3 INTEGER,n4 INTEGER,n5 INTEGER,n6 INTEGER,additional INTEGER,jackpot INTEGER)");}public void onUpgrade(SQLiteDatabase db,int o,int n){}public void replaceAll(List<Draw>ds){SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{for(Draw d:ds){ContentValues v=new ContentValues();v.put("contest",d.contest);v.put("date",d.date);for(int i=0;i<6;i++)v.put("n"+(i+1),d.n[i]);v.put("additional",d.additional);v.put("jackpot",d.jackpot);db.insertWithOnConflict("draws",null,v,SQLiteDatabase.CONFLICT_REPLACE);}db.setTransactionSuccessful();}finally{db.endTransaction();}}public List<Draw>all(){ArrayList<Draw>o=new ArrayList<>();Cursor c=getReadableDatabase().rawQuery("SELECT contest,date,n1,n2,n3,n4,n5,n6,additional,jackpot FROM draws ORDER BY contest DESC",null);while(c.moveToNext())o.add(new Draw(c.getInt(0),c.getString(1),new int[]{c.getInt(2),c.getInt(3),c.getInt(4),c.getInt(5),c.getInt(6),c.getInt(7)},c.getInt(8),c.getLong(9)));c.close();return o;}}
